<?php require __DIR__.'/../includes/bootstrap.php';require_admin();$message='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pairs=['store_name'=>trim($_POST['store_name']??''),'hero_title'=>trim($_POST['hero_title']??''),'hero_text'=>trim($_POST['hero_text']??'')];foreach($pairs as $k=>$v){$s=$pdo->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');$s->execute([$k,$v]);}try{$img=upload_image($_FILES['banner']??[],'settings');if($img){$s=$pdo->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');$s->execute(['banner_image',$img]);}$bg=upload_image($_FILES['background']??[],'settings');if($bg){$s=$pdo->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');$s->execute(['background_image',$bg]);}}catch(Throwable $e){$message=$e->getMessage();}if(!$message)$message='تم حفظ الإعدادات.';}$page_title='إعدادات المتجر';require __DIR__.'/../includes/header.php';?><main class="container"><h1 class="gold">إعدادات المتجر</h1><?php require __DIR__.'/nav.php';?><div class="panel"><?php if($message):?><div class="alert"><?=e($message)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="field"><label>اسم المتجر</label><input name="store_name" value="<?=e(setting('store_name',$config['site_name']))?>"></div><div class="field"><label>عنوان البانر</label><input name="hero_title" value="<?=e(setting('hero_title','بوتيك السعادة'))?>"></div><div class="field"><label>وصف البانر</label><textarea name="hero_text"><?=e(setting('hero_text','اكتشف مجموعتنا المختارة واستمتع بتجربة تسوق مريحة وخاصة.'))?></textarea></div><div class="field"><label>صورة البانر</label><input type="file" name="banner" accept="image/jpeg,image/png,image/webp"></div><div class="field"><label>خلفية صفحات المتجر</label><input type="file" name="background" accept="image/jpeg,image/png,image/webp"></div><button class="btn">حفظ الإعدادات</button></form></div></main><?php require __DIR__.'/../includes/footer.php';?>
